// Projects → the blueprint stage summary, AS GRAPH SOURCE (#4238, epic #3604) — one of the last reachable components that was not a
// record. Its `provides: "@/features/planner/blueprints/BlueprintModals"` makes the runtime loader vendor THIS
// source wherever a graph component imports that specifier, with the registered module as the
// fallback. Transcribed from the live feature file; the CSS import is dropped (the host owns the
// stylesheet) and specifiers are absolute. Behaviour runs here.
// Blueprint preview types + the shared stage-summary view (#609 slice 5) — ported from the design's
// gist.jsx. The `PreviewBlueprint` shape drives resolve/import across the gist client (gist.ts); the
// `StageSummary` render is reused by the plan stage bar (#3802: the paste-URL `ImportModal` was
// removed with the gist-import modals — the not-yet-downloaded gists now live in the persistent
// `CloudBlueprints` column on the ProjectSetupPage).

import { Chip } from "@/shared/ui/data/Chip";
import { Ic } from "@/features/planner/blueprints/blueprintIcons";
import { IconBox } from "@/shared/ui/data/IconBox";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import type { Blueprint, BlueprintStage } from "@/features/planner/stages/blueprints";
import type { SkillPayload } from "@/features/planner/blueprints/blueprintSkills";

// blueprintCatalog.ts imports `@/features/planner/stages/blueprints` for STAGE_DEFS, which re-exports
// (transitively, via ./blueprintBuiltins) a module that calls `import.meta.glob` — a build step this
// preview sandbox's esbuild pipeline doesn't support. Importing `stageKind`/`tint`/`hue` as VALUES
// crashes the whole module at load time; these local stand-ins replace them, keeping the render logic
// unchanged. `Blueprint`/`BlueprintStage` above stay TYPE-only imports (erased at build time, safe).
function stageKind(_key: string): { glyph: string; h: number } { return { glyph: "card", h: 220 }; }
function tint(h: number, alpha: number): string { return `oklch(0.72 0.12 ${h} / ${alpha})`; }
function hue(h: number): string { return `oklch(0.72 0.14 ${h})`; }

/** A resolved import/preview blueprint (subset enough to preview + import). */
export interface PreviewBlueprint {
  name: string; icon: string; h: number; author?: string; rev?: string; sections: BlueprintStage[];
  /** The upstream gist id this preview came from (#955) — recorded on import so a re-import is
   *  recognized (dedupe → update in place) and the import page can show its sync state. */
  gistId?: string;
  /** The fully-coerced blueprint (#897) — carried so import preserves blueprint-wide
   *  skills/mcp/category/mode instead of reconstructing from the lossy preview subset. */
  blueprint?: Blueprint;
  /** Skill content embedded in the share (#897 Phase 5b) — reconstituted into the library on import. */
  bundled?: SkillPayload[];
}

const DEFAULT_SECTIONS: BlueprintStage[] = [
  { key: "discovery", name: "Discovery", skills: [], mcp: [], prompt: "Interview the user about their app idea, capture goals and constraints." } as unknown as BlueprintStage,
  { key: "model", name: "Data model", skills: ["schema-design"], mcp: [], gateRule: "model approved", prompt: "Derive the data model from the discovery notes." } as unknown as BlueprintStage,
];

export function StageSummary({ sections = DEFAULT_SECTIONS }: { sections?: BlueprintStage[] }) {
  return (
    <Stack gap={4}>
      {sections.map((s, i) => {
        const k = stageKind(s.key);
        const caps = (s.skills?.length ?? 0) + (s.mcp?.length ?? 0);
        return (
          <Stack key={s.uid ?? i} gap={4} style={{ padding: "5px 0" }}>
            <Row gap={9}>
              <Box as="span" className="mono dim" style={{ fontSize: 9.5, width: 16 }}>{String(i + 1).padStart(2, "0")}</Box>
              <IconBox size={22} radius={5} background={tint(k.h, 0.16)} color={hue(k.h)}><Ic n={k.glyph} size={13} /></IconBox>
              <Text as="span" size={11.5} className="mono" style={{ color: "var(--fg)" }}>{s.name}</Text>
              <Box as="span" style={{ flex: 1 }} />
              {caps > 0 && <Text as="span" className="hint mono">{caps} attached</Text>}
              {s.gateRule && <Chip tone="accent">gate</Chip>}
            </Row>
            {/* The prompt is the substance of the stage (#1268) — dense text under the row, the
                icon as its index. pre-wrap keeps the prompt's own line breaks. */}
            {s.prompt?.trim() && (
              <Box className="mono" style={{ marginLeft: 25, fontSize: 10, lineHeight: 1.5, color: "var(--fg-dim)", whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
                {s.prompt.trim()}
              </Box>
            )}
          </Stack>
        );
      })}
    </Stack>
  );
}
